<%_
// 有 NSFW 人设的角色名单；使用世界书条目的正式名称
var nsfwChars = ['苏晚棠', '苏晚月', '栖云', '栖月', '翠儿', '林知夏', '沈清晏', '柳氏', '方子衿', '洪天妹', '陆挽星', '柳如是', '白瑶', '陈圆圆', '周皇后', '朱徽媞', '安娜', '温素弦', '张嫣', '周氏', '杨尔铭'];

// 人际网络可能使用封号等别名，取条目时仍回到正式名称
var nsfwAliases = {
  '朱徽媞': ['朱徽媞', '乐安公主']
};

// 读取当前场景
var scene = getvar('stat_data.世界运转.场景', { defaults: 'SFW' });

if (scene === 'NSFW') {
  // 当前场景统一名单；旧版每人一份的“是否在场”已废弃
  var presentChars = getvar('stat_data.人际网络.在场角色', { defaults: [] });
  if (!Array.isArray(presentChars)) presentChars = [];

  for (var i = 0; i < nsfwChars.length; i++) {
    var name = nsfwChars[i];
    var present = false;
    var lookupNames = nsfwAliases[name] || [name];

    // 正式姓名或已登记别名任一命中即可
    for (var aliasIndex = 0; aliasIndex < lookupNames.length; aliasIndex++) {
      if (presentChars.indexOf(lookupNames[aliasIndex]) !== -1) {
        present = true;
        break;
      }
    }

    // 仅注入在场角色的 NSFW 人设
    if (present) {
_%>
<%- await getwi(name + '_NSFW') %>
<%_
    }
  }
}
_%>

